def reduce_current(path,raw):
 raw=authorization_delta.reduce_if_selected(path,raw)
 if path not in SOURCE_INPUTS:return raw
 if type(raw)is not bytes or hashlib.sha256(raw).hexdigest()!=SOURCE_INPUTS[path]:raise ValueError('unreviewed OAuth code source')
 for added,removed in EDITS[path]:
  if raw.count(added)!=1:raise ValueError('OAuth code inverse shape changed')
  raw=raw.replace(added,removed,1)
 if hashlib.sha256(raw).hexdigest()!=BASE_PINS[path]:raise ValueError('OAuth code changed other native bytes')
 return raw

def reduce_if_selected(path,raw):
 raw=authorization_delta.reduce_if_selected(path,raw)
 if path not in SOURCE_INPUTS:return raw
 if type(raw)is bytes and hashlib.sha256(raw).hexdigest()==BASE_PINS[path]:return raw
 return reduce_current(path,raw)
def assert_cohort(root,reader):
 authorization_delta.assert_cohort(root,reader)
 original_reader=reader
 reader=lambda p:authorization_delta.reduce_if_selected(str(p.relative_to(root)),original_reader(p))
 from pathlib import Path
 observed={path:hashlib.sha256(reader(Path(root)/path)).hexdigest() for path in SOURCE_INPUTS}
 if observed!=SOURCE_INPUTS and observed!=BASE_PINS:raise ValueError('mixed or unreviewed OAuth code cohort')
 return observed==SOURCE_INPUTS
